tool_input.command:
curl -s -G 'http://localhost:16686/jaeger/ui/api/traces' --data-urlencode 'service=product-catalog' --data-urlencode 'lookback=2h' --data-urlencode 'limit=20' -o /tmp/pc_traces.json; python3 -c "
import json
d=json.load(open('/tmp/pc_traces.json'))
print('total traces:', len(d.get('data',[])))
for t in d.get('data',[])[:20]:
    for s in t['spans']:
        tags={tg['key']:tg['value'] for tg in s.get('tags',[])}
        if tags.get('error') or tags.get('otel.status_code')=='ERROR':
            print(t['traceID'], s['operationName'], tags.get('error'), tags.get('otel.status_code'), tags.get('otel.status_description'))
"

